CREATE DATABASE IF NOT EXISTS limitless_visual CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE limitless_visual;
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,email VARCHAR(254) NOT NULL,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,phone VARCHAR(40) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_customers_email(email)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id CHAR(36) NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','paid','payment_failed','cancelled','refunded') NOT NULL DEFAULT 'pending',checkout_mode ENUM('payment','subscription') NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'usd',total_amount INT UNSIGNED NOT NULL,project_type VARCHAR(80) NOT NULL,timeline VARCHAR(80) NOT NULL,details TEXT NOT NULL,stripe_checkout_session_id VARCHAR(255) NULL,stripe_payment_intent_id VARCHAR(255) NULL,stripe_customer_id VARCHAR(255) NULL,paid_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_orders_checkout_session(stripe_checkout_session_id),KEY idx_orders_customer(customer_id),KEY idx_orders_status_created(status,created_at),CONSTRAINT fk_orders_customer FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,order_id CHAR(36) NOT NULL,product_id VARCHAR(120) NOT NULL,product_name VARCHAR(160) NOT NULL,quantity SMALLINT UNSIGNED NOT NULL,unit_amount INT UNSIGNED NOT NULL,PRIMARY KEY(id),KEY idx_order_items_order(order_id),CONSTRAINT fk_order_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inquiries (id CHAR(36) NOT NULL,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(40) NULL,project_type VARCHAR(80) NOT NULL,timeline VARCHAR(80) NOT NULL,details TEXT NOT NULL,selected_services TEXT NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_inquiries_email(email),KEY idx_inquiries_created(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stripe_events (event_id VARCHAR(255) NOT NULL,event_type VARCHAR(120) NOT NULL,processed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id)) ENGINE=InnoDB;
